#define STB_IMAGE_IMPLEMENTATION
#include "stb_image.h"
#include "Assets.h"
#include "Renderer.h"
#include <iostream>

// In a real scenario, these headers are generated by a script converting PNGs to bytes.
// For this implementation, we'll assume the conversion has happened.
#include "test_asset.h" 

const std::vector<TextureData> g_assetLibrary = {
    { test_png_data, 2, 2, 4, "test_sprite" }
};

TextureID loadTextureFromMemory(const TextureData& asset)
{
    stbi_set_flip_vertically_on_load(true);
    unsigned char* pixels = stbi_load_from_memory(asset.data, 0, nullptr, nullptr, nullptr, 4);

    if (!pixels) {
        std::cerr << "Failed to decode embedded asset: " << asset.name << std::endl;
        return 0;
    }

    GLuint texture;
    glGenTextures(1, &texture);
    glBindTexture(GL_TEXTURE_2D, texture);

    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_REPEAT);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_REPEAT);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST);

    glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, asset.width, asset.height, 0, GL_RGBA, GL_UNSIGNED_BYTE, pixels);
    stbi_image_free(pixels);

    return texture;
}
